# Batch 2 — stotras (Sanskrit, traditional). Text checked against published versions; meanings are original.
S, D = "shloka", "doha"

SHIV_TANDAV = [
 (S,"जटाटवीगलज्जलप्रवाहपावितस्थले\nगलेऽवलम्ब्य लम्बितां भुजङ्गतुङ्गमालिकाम्।\nडमड्डमड्डमड्डमन्निनादवड्डमर्वयं\nचकार चण्डताण्डवं तनोतु नः शिवः शिवम्॥","जटाओं के वन से बहती गंगा से पवित्र स्थान पर, गले में बड़े सर्पों की माला लटकाए, डमरू की डम-डम ध्वनि के साथ जिन्होंने प्रचंड तांडव किया, वे शिव हमारा कल्याण करें।"),
 (S,"जटाकटाहसम्भ्रमभ्रमन्निलिम्पनिर्झरी\nविलोलवीचिवल्लरीविराजमानमूर्धनि।\nधगद्धगद्धगज्ज्वलल्ललाटपट्टपावके\nकिशोरचन्द्रशेखरे रतिः प्रतिक्षणं मम॥","जिनकी जटाओं के कड़ाह में घूमती गंगा की चंचल लहरें सिर पर शोभा देती हैं, जिनके माथे पर धग-धग अग्नि जलती है और सिर पर बाल-चंद्रमा है, उन शिव में मेरा प्रेम हर क्षण बना रहे।"),
 (S,"धराधरेन्द्रनन्दिनीविलासबन्धुबन्धुर\nस्फुरद्दिगन्तसन्ततिप्रमोदमानमानसे।\nकृपाकटाक्षधोरणीनिरुद्धदुर्धरापदि\nक्वचिद्दिगम्बरे मनो विनोदमेतु वस्तुनि॥","जो पर्वतराज की पुत्री पार्वती के विलास के साथी हैं, जिनका मन सारी दिशाओं के प्राणियों को देखकर प्रसन्न रहता है, जिनकी कृपा-दृष्टि बड़ी-बड़ी विपत्तियाँ रोक देती है, उन दिगंबर शिव में मेरा मन आनंद पाए।"),
 (S,"जटाभुजङ्गपिङ्गलस्फुरत्फणामणिप्रभा\nकदम्बकुङ्कुमद्रवप्रलिप्तदिग्वधूमुखे।\nमदान्धसिन्धुरस्फुरत्त्वगुत्तरीयमेदुरे\nमनो विनोदमद्भुतं बिभर्तु भूतभर्तरि॥","जटाओं के सर्पों की फणों की मणियों की पीली चमक से जिनकी दिशाएँ रूपी स्त्रियों के मुख केसर से रँगे लगते हैं, जो मतवाले हाथी की खाल ओढ़ते हैं, उन प्राणियों के स्वामी शिव में मेरा मन अद्भुत आनंद पाए।"),
 (S,"सहस्रलोचनप्रभृत्यशेषलेखशेखर\nप्रसूनधूलिधोरणी विधूसराङ्घ्रिपीठभूः।\nभुजङ्गराजमालया निबद्धजाटजूटक\nश्रियै चिराय जायतां चकोरबन्धुशेखरः॥","इंद्र आदि सब देवताओं के सिर के फूलों की धूल से जिनके चरण धूसर हैं, जिनकी जटा सर्पराज की माला से बँधी है, वे चंद्रशेखर शिव हमें लंबे समय तक समृद्धि दें।"),
 (S,"ललाटचत्वरज्वलद्धनञ्जयस्फुलिङ्गभा\nनिपीतपञ्चसायकं नमन्निलिम्पनायकम्।\nसुधामयूखलेखया विराजमानशेखरं\nमहाकपालिसम्पदेशिरोजटालमस्तु नः॥","जिन्होंने माथे की अग्नि की चिंगारी से कामदेव को भस्म किया, जिन्हें देवताओं के राजा प्रणाम करते हैं, जिनके सिर पर चंद्रमा की कला शोभा देती है, उन जटाधारी महाकपाली शिव का वैभव हमें मिले।"),
 (S,"करालभालपट्टिकाधगद्धगद्धगज्ज्वल\nद्धनञ्जयाहुतीकृतप्रचण्डपञ्चसायके।\nधराधरेन्द्रनन्दिनीकुचाग्रचित्रपत्रक\nप्रकल्पनैकशिल्पिनि त्रिलोचने रतिर्मम॥","जिन्होंने भयानक माथे पर धधकती अग्नि में प्रचंड कामदेव की आहुति दे दी, जो पार्वती के श्रृंगार की चित्रकारी करने वाले अनोखे कलाकार हैं, उन त्रिनेत्र शिव में मेरा प्रेम हो।"),
 (S,"नवीनमेघमण्डली निरुद्धदुर्धरस्फुरत्\nकुहूनिशीथिनीतमः प्रबन्धबद्धकन्धरः।\nनिलिम्पनिर्झरीधरस्तनोतु कृत्तिसिन्धुरः\nकलानिधानबन्धुरः श्रियं जगद्धुरंधरः॥","जिनका कंठ नए बादलों और अमावस की आधी रात के अंधेरे जैसा काला है, जो गंगा धारण करते हैं, हाथी की खाल पहनते हैं, चंद्रमा से सुंदर हैं और जगत का भार उठाते हैं, वे शिव हमें समृद्धि दें।"),
 (S,"प्रफुल्लनीलपङ्कजप्रपञ्चकालिमप्रभा\nवलम्बिकण्ठकन्दलीरुचिप्रबद्धकन्धरम्।\nस्मरच्छिदं पुरच्छिदं भवच्छिदं मखच्छिदं\nगजच्छिदान्धकच्छिदं तमन्तकच्छिदं भजे॥","खिले नीले कमल जैसे काले कंठ वाले, कामदेव, त्रिपुर, संसार, दक्ष-यज्ञ, गजासुर, अंधकासुर और यम का भी अंत करने वाले शिव का मैं भजन करता हूँ।"),
 (S,"अखर्वसर्वमङ्गलाकलाकदम्बमञ्जरी\nरसप्रवाहमाधुरी विजृम्भणामधुव्रतम्।\nस्मरान्तकं पुरान्तकं भवान्तकं मखान्तकं\nगजान्तकान्धकान्तकं तमन्तकान्तकं भजे॥","जो पार्वती की कलाओं के रस का आनंद लेने वाले भौंरे जैसे हैं, और कामदेव, त्रिपुर, संसार, यज्ञ, गजासुर, अंधकासुर और यम का अंत करने वाले हैं, उन शिव का मैं भजन करता हूँ।"),
 (S,"जयत्वदभ्रविभ्रमभ्रमद्भुजङ्गमश्वस\nद्विनिर्गमत्क्रमस्फुरत्करालभालहव्यवाट्।\nधिमिद्धिमिद्धिमिध्वनन्मृदङ्गतुङ्गमङ्गल\nध्वनिक्रमप्रवर्तित प्रचण्डताण्डवः शिवः॥","जिनके माथे की भयानक अग्नि तेज़ी से घूमते सर्पों की फुफकार से और भड़कती है, और जो मृदंग की धिम-धिम मंगल ध्वनि की लय पर प्रचंड तांडव करते हैं, उन शिव की जय हो।"),
 (S,"दृषद्विचित्रतल्पयोर्भुजङ्गमौक्तिकस्रजोर्\nगरिष्ठरत्नलोष्ठयोः सुहृद्विपक्षपक्षयोः।\nतृणारविन्दचक्षुषोः प्रजामहीमहेन्द्रयोः\nसमप्रवृत्तिकः कदा सदाशिवं भजाम्यहम्॥","पत्थर और सुंदर बिस्तर, साँप और मोती की माला, कीमती रत्न और मिट्टी का ढेला, मित्र और शत्रु, तिनका और कमल-नयनी, प्रजा और राजा — इन सबको समान देखते हुए मैं कब सदाशिव का भजन करूँगा?"),
 (S,"कदा निलिम्पनिर्झरीनिकुञ्जकोटरे वसन्\nविमुक्तदुर्मतिः सदा शिरः स्थमञ्जलिं वहन्।\nविमुक्तलोललोचनो ललामभाललग्नकः\nशिवेति मंत्रमुच्चरन् कदा सुखी भवाम्यहम्॥","कब मैं गंगा के किनारे कुंज में रहकर, बुरे विचारों से मुक्त होकर, सिर पर हाथ जोड़े, चंचल नज़रें छोड़कर, शिव में मन लगाकर ‘शिव’ मंत्र जपता हुआ सुखी होऊँगा?"),
 (S,"निलिम्पनाथनागरीकदम्बमौलिमल्लिका\nनिगुम्फनिर्भरक्षरन्मधूष्णिकामनोहरः।\nतनोतु नो मनोमुदं विनोदिनीमहर्निशं\nपरश्रियः परं पदं तदङ्गजत्विषां चयः॥","देव-स्त्रियों के बालों में गुँथे फूलों से टपकते पराग से सुंदर, परम शोभा के धाम शिव के अंगों की कांति हमारे मन को दिन-रात आनंद दे।"),
 (S,"प्रचण्डवाडवानलप्रभाशुभप्रचारणी\nमहाष्टसिद्धिकामिनीजनावहूतजल्पना।\nविमुक्तवामलोचनाविवाहकालिकध्वनिः\nशिवेति मन्त्रभूषणा जगज्जयाय जायताम्॥","पापों को बड़वाग्नि की तरह जलाने वाली, आठों सिद्धियों को बुलाने वाली, शिव-पार्वती विवाह के समय गूँजने वाली ‘शिव’ मंत्र की ध्वनि जगत की विजय के लिए हो।"),
 (S,"इमं हि नित्यमेवमुक्तमुत्तमोत्तमं स्तवं\nपठन्स्मरन्ब्रुवन्नरो विशुद्धिमेतिसंततम्।\nहरे गुरौ सुभक्तिमाशु याति नान्यथा गतिं\nविमोहनं हि देहिनां सुशङ्करस्य चिंतनम्॥","जो इस उत्तम स्तोत्र को रोज़ पढ़ता, याद करता या बोलता है, वह सदा शुद्ध होता है और जल्दी ही गुरु शिव की भक्ति पाता है; शंकर का चिंतन ही प्राणियों का मोह दूर करता है।"),
 (S,"पूजावसानसमये दशवक्त्रगीतं\nयः शम्भुपूजनपरं पठति प्रदोषे।\nतस्य स्थिरां रथगजेन्द्रतुरङ्गयुक्तां\nलक्ष्मीं सदैव सुमुखिं प्रददाति शम्भुः॥","जो प्रदोष काल में शिव-पूजा के अंत में रावण द्वारा गाया यह स्तोत्र पढ़ता है, शंभु उसे रथ, हाथी और घोड़ों से युक्त स्थिर लक्ष्मी देते हैं।"),
]

SHIV_PANCHAKSHAR = [
 (S,"नागेन्द्रहाराय त्रिलोचनाय\nभस्माङ्गरागाय महेश्वराय।\nनित्याय शुद्धाय दिगम्बराय\nतस्मै नकाराय नमः शिवाय॥","जिनके गले में सर्पों का हार है, जिनके तीन नेत्र हैं, भस्म ही जिनका श्रृंगार है, उन नित्य, शुद्ध, दिगंबर महेश्वर — ‘न’ अक्षर रूप शिव को नमस्कार।"),
 (S,"मन्दाकिनीसलिलचन्दनचर्चिताय\nनन्दीश्वरप्रमथनाथमहेश्वराय।\nमन्दारपुष्पबहुपुष्पसुपूजिताय\nतस्मै मकाराय नमः शिवाय॥","गंगाजल और चंदन से जिनकी पूजा होती है, जो नंदी और शिवगणों के स्वामी हैं, मंदार और अनेक फूलों से पूजित — ‘म’ अक्षर रूप शिव को नमस्कार।"),
 (S,"शिवाय गौरीवदनाब्जवृन्द\nसूर्याय दक्षाध्वरनाशकाय।\nश्रीनीलकण्ठाय वृषध्वजाय\nतस्मै शिकाराय नमः शिवाय॥","जो कल्याण स्वरूप हैं, पार्वती के मुख-कमल को खिलाने वाले सूर्य हैं, दक्ष-यज्ञ का नाश करने वाले, नीलकंठ और बैल की ध्वजा वाले — ‘शि’ अक्षर रूप शिव को नमस्कार।"),
 (S,"वसिष्ठकुम्भोद्भवगौतमार्य\nमुनीन्द्रदेवार्चितशेखराय।\nचन्द्रार्कवैश्वानरलोचनाय\nतस्मै वकाराय नमः शिवाय॥","वसिष्ठ, अगस्त्य, गौतम जैसे मुनि और देवता जिनकी पूजा करते हैं, चंद्रमा, सूर्य और अग्नि जिनके नेत्र हैं — ‘व’ अक्षर रूप शिव को नमस्कार।"),
 (S,"यक्षस्वरूपाय जटाधराय\nपिनाकहस्ताय सनातनाय।\nदिव्याय देवाय दिगम्बराय\nतस्मै यकाराय नमः शिवाय॥","यक्ष रूप धारण करने वाले, जटाधारी, हाथ में पिनाक धनुष वाले, सनातन, दिव्य, दिगंबर देव — ‘य’ अक्षर रूप शिव को नमस्कार।"),
 (D,"पञ्चाक्षरमिदं पुण्यं यः पठेच्छिवसन्निधौ।\nशिवलोकमवाप्नोति शिवेन सह मोदते॥","जो शिव के पास बैठकर यह पवित्र पंचाक्षर स्तोत्र पढ़ता है, वह शिवलोक पाता है और शिव के साथ आनंदित होता है।"),
]

LINGASHTAKAM = [
 (S,"ब्रह्ममुरारिसुरार्चितलिङ्गं\nनिर्मलभासितशोभितलिङ्गम्।\nजन्मजदुःखविनाशकलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","ब्रह्मा, विष्णु और देवताओं द्वारा पूजित, निर्मल प्रकाश से शोभित, जन्म से मिलने वाले दुखों का नाश करने वाले सदाशिव लिंग को मैं प्रणाम करता हूँ।"),
 (S,"देवमुनिप्रवरार्चितलिङ्गं\nकामदहं करुणाकरलिङ्गम्।\nरावणदर्पविनाशनलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","देवताओं और श्रेष्ठ मुनियों द्वारा पूजित, कामदेव को भस्म करने वाले, करुणा के सागर, रावण का घमंड तोड़ने वाले सदाशिव लिंग को प्रणाम।"),
 (S,"सर्वसुगन्धिसुलेपितलिङ्गं\nबुद्धिविवर्धनकारणलिङ्गम्।\nसिद्धसुरासुरवन्दितलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","सब सुगंधित वस्तुओं से लेपित, बुद्धि बढ़ाने वाले, सिद्धों, देवताओं और असुरों द्वारा वंदित सदाशिव लिंग को प्रणाम।"),
 (S,"कनकमहामणिभूषितलिङ्गं\nफणिपतिवेष्टितशोभितलिङ्गम्।\nदक्षसुयज्ञविनाशनलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","सोने और बड़ी मणियों से सजे, सर्पराज से लिपटे हुए सुंदर, दक्ष के यज्ञ का नाश करने वाले सदाशिव लिंग को प्रणाम।"),
 (S,"कुङ्कुमचन्दनलेपितलिङ्गं\nपङ्कजहारसुशोभितलिङ्गम्।\nसञ्चितपापविनाशनलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","कुमकुम और चंदन से लेपित, कमलों के हार से शोभित, इकट्ठे पापों का नाश करने वाले सदाशिव लिंग को प्रणाम।"),
 (S,"देवगणार्चितसेवितलिङ्गं\nभावैर्भक्तिभिरेव च लिङ्गम्।\nदिनकरकोटिप्रभाकरलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","देवगणों द्वारा भाव और भक्ति से पूजित-सेवित, करोड़ों सूर्यों जैसी आभा वाले सदाशिव लिंग को प्रणाम।"),
 (S,"अष्टदलोपरिवेष्टितलिङ्गं\nसर्वसमुद्भवकारणलिङ्गम्।\nअष्टदरिद्रविनाशितलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","आठ पंखुड़ियों वाले कमल से घिरे, सारी सृष्टि के कारण, आठ तरह की दरिद्रता मिटाने वाले सदाशिव लिंग को प्रणाम।"),
 (S,"सुरगुरुसुरवरपूजितलिङ्गं\nसुरवनपुष्पसदार्चितलिङ्गम्।\nपरात्परं परमात्मकलिङ्गं\nतत् प्रणमामि सदाशिवलिङ्गम्॥","देवगुरु बृहस्पति और श्रेष्ठ देवताओं द्वारा पूजित, स्वर्ग के उपवन के फूलों से सदा पूजित, परे से भी परे, परमात्म-स्वरूप सदाशिव लिंग को प्रणाम।"),
 (D,"लिङ्गाष्टकमिदं पुण्यं यः पठेत् शिवसन्निधौ।\nशिवलोकमवाप्नोति शिवेन सह मोदते॥","जो शिव के पास बैठकर यह पवित्र लिंगाष्टक पढ़ता है, वह शिवलोक पाता है और शिव के साथ आनंदित होता है।"),
]

MAHISHASURA_MARDINI = [
 (S,"अयि गिरिनन्दिनि नन्दितमेदिनि विश्वविनोदिनि नन्दिनुते\nगिरिवरविन्ध्यशिरोऽधिनिवासिनि विष्णुविलासिनि जिष्णुनुते।\nभगवति हे शितिकण्ठकुटुम्बिनि भूरिकुटुम्बिनि भूरिकृते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","हे पर्वत-पुत्री, पृथ्वी को आनंद देने वाली, विश्व को प्रसन्न रखने वाली, नंदी द्वारा पूजित, विंध्य पर्वत पर रहने वाली, विष्णु के साथ क्रीड़ा करने वाली, इंद्र द्वारा पूजित, नीलकंठ शिव की पत्नी, विशाल परिवार वाली और बहुत कुछ करने वाली भगवती — हे महिषासुर का वध करने वाली, सुंदर जटाओं वाली शैलपुत्री, आपकी जय हो।"),
 (S,"सुरवरवर्षिणि दुर्धरधर्षिणि दुर्मुखमर्षिणि हर्षरते\nत्रिभुवनपोषिणि शङ्करतोषिणि किल्बिषमोषिणि घोषरते।\nदनुजनिरोषिणि दितिसुतरोषिणि दुर्मदशोषिणि सिन्धुसुते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","देवताओं पर वरदान बरसाने वाली, दुर्धर और दुर्मुख असुरों को हराने वाली, सदा आनंद में रहने वाली, तीनों लोकों का पोषण करने वाली, शंकर को प्रसन्न करने वाली, पाप हरने वाली, दानवों पर क्रोध करने वाली, घमंड सुखाने वाली देवी, आपकी जय हो।"),
 (S,"अयि जगदम्ब मदम्ब कदम्ब वनप्रियवासिनि हासरते\nशिखरि शिरोमणि तुङ्गहिमालय शृङ्गनिजालय मध्यगते।\nमधुमधुरे मधुकैटभगञ्जिनि कैटभभञ्जिनि रासरते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","हे जगत की माँ, मेरी माँ, कदंब वन में रहना पसंद करने वाली, सदा मुस्कुराने वाली, ऊँचे हिमालय की चोटी पर अपने घर में रहने वाली, मधु जैसी मधुर, मधु-कैटभ का नाश करने वाली, रास में रमने वाली देवी, आपकी जय हो।"),
 (S,"अयि शतखण्ड विखण्डितरुण्ड वितुण्डितशुण्ड गजाधिपते\nरिपुगजगण्ड विदारणचण्ड पराक्रमशुण्ड मृगाधिपते।\nनिजभुजदण्ड निपातितखण्ड विपातितमुण्ड भटाधिपते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जिन्होंने शत्रुओं के धड़ के सौ टुकड़े कर दिए, हाथियों की सूँड़ें काट दीं, जिनका सिंह शत्रु-हाथियों के मस्तक फाड़ देता है, जिन्होंने अपनी भुजाओं से योद्धाओं के सिर गिरा दिए — उन देवी की जय हो।"),
 (S,"अयि रणदुर्मद शत्रुवधोदित दुर्धरनिर्जर शक्तिभृते\nचतुरविचार धुरीणमहाशिव दूतकृत प्रमथाधिपते।\nदुरितदुरीह दुराशयदुर्मति दानवदूत कृतान्तमते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","युद्ध में घमंडी शत्रुओं को मारने के लिए अजेय शक्ति धारण करने वाली, बुद्धिमान महाशिव को अपना दूत बनाने वाली, बुरे इरादों वाले दानवों के दूतों का अंत करने वाली देवी की जय हो।"),
 (S,"अयि शरणागत वैरिवधूवर वीरवराभय दायकरे\nत्रिभुवनमस्तक शूलविरोधि शिरोऽधिकृतामल शूलकरे।\nदुमिदुमितामर दुन्दुभिनादमहोमुखरीकृत दिङ्मकरे\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जो शरण में आई शत्रुओं की पत्नियों को भी अभय देती हैं, तीनों लोकों के कष्ट मिटाने वाला निर्मल त्रिशूल धारण करती हैं, जिनके लिए देवताओं के नगाड़े दिशाओं को गुँजा देते हैं — उन देवी की जय हो।"),
 (S,"अयि निजहुङ्कृति मात्रनिराकृत धूम्रविलोचन धूम्रशते\nसमरविशोषित शोणितबीज समुद्भवशोणित बीजलते।\nशिवशिवशुम्भ निशुम्भमहाहव तर्पितभूत पिशाचरते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जिन्होंने केवल अपनी हुंकार से धूम्रलोचन को राख कर दिया, युद्ध में रक्तबीज और उससे उपजे असुरों को सुखा दिया, शुंभ-निशुंभ के महायुद्ध से भूत-पिशाचों को तृप्त किया — उन देवी की जय हो।"),
 (S,"धनुरनुषङ्ग रणक्षणसङ्ग परिस्फुरदङ्ग नटत्कटके\nकनकपिशङ्ग पृषत्कनिषङ्ग रसद्भटशृङ्ग हताबटुके।\nकृतचतुरङ्ग बलक्षितिरङ्ग घटद्बहुरङ्ग रटद्बटुके\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","युद्ध में धनुष के साथ चमकते अंगों और खनकते कंगनों वाली, सुनहरे बाणों से योद्धाओं को मारने वाली, चतुरंगिणी सेना को रणभूमि में गिराने वाली देवी की जय हो।"),
 (S,"सुरललना ततथेयि तथेयि कृताभिनयोदर नृत्यरते\nकृत कुकुथः कुकुथो गडदादिकताल कुतूहल गानरते।\nधुधुकुट धुक्कुट धिंधिमित ध्वनि धीर मृदंग निनादरते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जो देव-स्त्रियों के ‘तत-थेई’ नृत्य, ताल-बद्ध गीतों और मृदंग की ‘धुधुकुट-धिंधिमि’ ध्वनि में आनंद लेती हैं, उन देवी की जय हो।"),
 (S,"जय जय जप्य जयेजयशब्द परस्तुति तत्परविश्वनुते\nझणझणझिञ्झिमि झिङ्कृत नूपुरशिञ्जितमोहित भूतपते।\nनटित नटार्ध नटी नट नायक नाटितनाट्य सुगानरते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जिनकी ‘जय-जय’ के साथ सारा विश्व स्तुति करता है, जिनके नूपुरों की झनकार से शिव मोहित होते हैं, जो अर्धनारीश्वर रूप में नृत्य और सुंदर गायन में रमती हैं — उन देवी की जय हो।"),
 (S,"अयि सुमनःसुमनःसुमनः सुमनःसुमनोहरकान्तियुते\nश्रितरजनी रजनीरजनी रजनीरजनी करवक्त्रवृते।\nसुनयनविभ्रमर भ्रमरभ्रमर भ्रमरभ्रमराधिपते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","अच्छे मन वाले देवताओं को प्रिय, फूलों जैसी सुंदर कांति वाली, चंद्रमा जैसे मुख वाली, भौंरों जैसी चंचल सुंदर आँखों वाली देवी की जय हो।"),
 (S,"सहितमहाहव मल्लमतल्लिक मल्लितरल्लक मल्लरते\nविरचितवल्लिक पल्लिकमल्लिक झिल्लिकभिल्लिक वर्गवृते।\nशितकृतफुल्ल समुल्लसितारुण तल्लजपल्लव सल्ललिते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","महायुद्ध में श्रेष्ठ योद्धाओं के साथ लड़ने वाली, लताओं जैसी भील-स्त्रियों से घिरी, खिले हुए लाल कोमल पत्तों जैसी सुंदर देवी की जय हो।"),
 (S,"अविरलगण्ड गलन्मदमेदुर मत्तमतङ्ग जराजपते\nत्रिभुवनभूषण भूतकलानिधि रूपपयोनिधि राजसुते।\nअयि सुदतीजन लालसमानस मोहन मन्मथराजसुते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","मतवाले गजराज जैसी शक्तिशाली, तीनों लोकों का आभूषण, चंद्रमा जैसी, रूप की सागर, पर्वतराज की पुत्री, सबके मन को मोहने वाली देवी की जय हो।"),
 (S,"कमलदलामल कोमलकान्ति कलाकलितामल भाललते\nसकलविलास कलानिलयक्रम केलिचलत्कल हंसकुले।\nअलिकुलसङ्कुल कुवलयमण्डल मौलिमिलद्बकुलालिकुले\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","कमल की पंखुड़ी जैसी कोमल कांति वाली, चंद्रकला से सजे निर्मल माथे वाली, हंसों जैसी चाल वाली, भौंरों से घिरे फूलों से सजे बालों वाली देवी की जय हो।"),
 (S,"करमुरलीरव वीजितकूजित लज्जितकोकिल मञ्जुमते\nमिलितपुलिन्द मनोहरगुञ्जित रञ्जितशैल निकुञ्जगते।\nनिजगणभूत महाशबरीगण सद्गुणसम्भृत केलितले\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जिनकी बाँसुरी की मधुर ध्वनि से कोयल भी लजा जाती है, जो पर्वत-कुंजों में भीलों के मधुर गीतों के बीच घूमती हैं, अपने गणों और शबरियों के साथ क्रीड़ा करती हैं — उन देवी की जय हो।"),
 (S,"कटितटपीत दुकूलविचित्र मयूखतिरस्कृत चन्द्ररुचे\nप्रणतसुरासुर मौलिमणिस्फुर दंशुलसन्नख चन्द्ररुचे।\nजितकनकाचल मौलिमदोर्जित निर्भरकुञ्जर कुम्भकुचे\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जिनके पीले रेशमी वस्त्र की चमक चंद्रमा को भी फीका कर देती है, जिनके नख प्रणाम करते देवताओं-असुरों के मुकुट की मणियों से चमकते हैं — उन देवी की जय हो।"),
 (S,"विजितसहस्रकरैक सहस्रकरैक सहस्रकरैकनुते\nकृतसुरतारक सङ्गरतारक सङ्गरतारक सूनुसुते।\nसुरथसमाधि समानसमाधि समाधिसमाधि सुजातरते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","हज़ार किरणों वाले सूर्य से भी अधिक तेजस्वी, सूर्य द्वारा पूजित, तारकासुर को मारने वाले कार्तिकेय की माता, राजा सुरथ और समाधि वैश्य की समाधि (तपस्या) से प्रसन्न होने वाली देवी की जय हो।"),
 (S,"पदकमलं करुणानिलये वरिवस्यति योऽनुदिनं सुशिवे\nअयि कमले कमलानिलये कमलानिलयः स कथं न भवेत्।\nतव पदमेव परम्पदमित्यनुशीलयतो मम किं न शिवे\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","हे करुणा की धाम, कल्याणी, जो रोज़ आपके चरण-कमलों की सेवा करता है, वह लक्ष्मी का निवास क्यों न बने? आपके चरण ही परम पद हैं — ऐसा मानने वाले मुझे क्या नहीं मिलेगा?"),
 (S,"कनकलसत्कलसिन्धुजलैरनुषिञ्चति तेगुणरङ्गभुवम्\nभजति स किं न शचीकुचकुम्भतटीपरिरम्भसुखानुभवम्।\nतव चरणं शरणं करवाणि नतामरवाणि निवासि शिवम्\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","जो सोने के कलशों के जल से आपके आँगन को सींचता है, वह स्वर्ग का सुख क्यों न पाए? हे देवताओं द्वारा पूजित, कल्याणी माँ, मैं आपके चरणों की शरण लेता हूँ।"),
 (S,"तव विमलेन्दुकुलं वदनेन्दुमलं सकलं ननु कूलयते\nकिमु पुरुहूतपुरीन्दु मुखी सुमुखीभिरसौ विमुखीक्रियते।\nमम तु मतं शिवनामधने भवती कृपया किमुत क्रियते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","आपके निर्मल चंद्र-मुख का दर्शन सब कुछ पवित्र कर देता है; उसे पाकर इंद्रपुरी की सुंदरियाँ भी फीकी लगती हैं। हे शिव-नाम रूपी धन वाली माँ, मेरा तो मानना है कि आपकी कृपा से क्या नहीं हो सकता?"),
 (S,"अयि मयि दीन दयालुतया कृपयैव त्वया भवितव्यमुमे\nअयि जगतो जननी कृपयासि यथासि तथानुमितासिरते।\nयदुचितमत्र भवत्युररीकुरुतादुरुतापमपाकुरुते\nजय जय हे महिषासुरमर्दिनि रम्यकपर्दिनि शैलसुते॥","हे उमा, मुझ दीन पर दया और कृपा करनी ही चाहिए; आप जगत की माता हैं, जैसी कृपालु हैं वैसी ही जानी जाती हैं। जो उचित हो वही कीजिए और मेरा भारी संताप दूर कीजिए — हे महिषासुरमर्दिनी, आपकी जय हो।"),
]

MADHURASHTAKAM = [
 (S,"अधरं मधुरं वदनं मधुरं\nनयनं मधुरं हसितं मधुरम्।\nहृदयं मधुरं गमनं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","उनके होंठ मधुर हैं, मुख मधुर है, आँखें मधुर हैं, हँसी मधुर है, हृदय मधुर है, चाल मधुर है — मधुरता के स्वामी (श्रीकृष्ण) का सब कुछ मधुर है।"),
 (S,"वचनं मधुरं चरितं मधुरं\nवसनं मधुरं वलितं मधुरम्।\nचलितं मधुरं भ्रमितं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","उनकी बोली मधुर है, चरित्र मधुर है, वस्त्र मधुर हैं, मुड़ना मधुर है, चलना मधुर है, घूमना मधुर है — सब कुछ मधुर है।"),
 (S,"वेणुर्मधुरो रेणुर्मधुरः\nपाणिर्मधुरः पादौ मधुरौ।\nनृत्यं मधुरं सख्यं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","उनकी बाँसुरी मधुर है, चरणों की धूल मधुर है, हाथ मधुर हैं, पैर मधुर हैं, नृत्य मधुर है, मित्रता मधुर है — सब कुछ मधुर है।"),
 (S,"गीतं मधुरं पीतं मधुरं\nभुक्तं मधुरं सुप्तं मधुरम्।\nरूपं मधुरं तिलकं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","उनका गीत मधुर है, पीना मधुर है, खाना मधुर है, सोना मधुर है, रूप मधुर है, तिलक मधुर है — सब कुछ मधुर है।"),
 (S,"करणं मधुरं तरणं मधुरं\nहरणं मधुरं रमणं मधुरम्।\nवमितं मधुरं शमितं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","उनके कर्म मधुर हैं, तारना मधुर है, (मन) हरना मधुर है, रमण मधुर है, (भोग) अर्पण मधुर है, शांति मधुर है — सब कुछ मधुर है।"),
 (S,"गुञ्जा मधुरा माला मधुरा\nयमुना मधुरा वीची मधुरा।\nसलिलं मधुरं कमलं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","उनकी गुंजा की माला मधुर है, फूलों की माला मधुर है, यमुना मधुर है, उसकी लहरें मधुर हैं, जल मधुर है, कमल मधुर है — सब कुछ मधुर है।"),
 (S,"गोपी मधुरा लीला मधुरा\nयुक्तं मधुरं मुक्तं मधुरम्।\nदृष्टं मधुरं शिष्टं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","गोपियाँ मधुर हैं, लीला मधुर है, मिलन मधुर है, विदाई मधुर है, देखना मधुर है, शिष्टता मधुर है — सब कुछ मधुर है।"),
 (S,"गोपा मधुरा गावो मधुरा\nयष्टिर्मधुरा सृष्टिर्मधुरा।\nदलितं मधुरं फलितं मधुरं\nमधुराधिपतेरखिलं मधुरम्॥","ग्वाले मधुर हैं, गायें मधुर हैं, लाठी मधुर है, सृष्टि मधुर है, (दुष्टों का) दमन मधुर है, फल देना मधुर है — मधुरता के स्वामी का सब कुछ मधुर है।"),
]

HANUMANASHTAK = [
 (S,"बाल समय रवि भक्षि लियो तब, तीनहुं लोक भयो अँधियारो।\nताहि सों त्रास भयो जग को, यह संकट काहु सों जात न टारो।\nदेवन आनि करी बिनती तब, छाँड़ि दियो रवि कष्ट निवारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","बचपन में आपने सूर्य को निगल लिया, तो तीनों लोकों में अँधेरा छा गया; यह संकट किसी से टल नहीं रहा था। देवताओं ने विनती की, तब आपने सूर्य को छोड़कर कष्ट दूर किया। हे कपि, संसार में कौन नहीं जानता कि आपका नाम संकटमोचन है।"),
 (S,"बालि की त्रास कपीस बसै गिरि, जात महाप्रभु पंथ निहारो।\nचौंकि महामुनि शाप दियो तब, चाहिय कौन बिचार बिचारो।\nकै द्विज रूप लिवाय महाप्रभु, सो तुम दास के शोक निवारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","बालि के डर से सुग्रीव पर्वत पर रहते थे और प्रभु राम की राह देखते थे; (बालि को) मुनि ने शाप दिया था, तब क्या उपाय करें — यह सोचकर आप ब्राह्मण रूप धरकर प्रभु को ले आए और अपने दास (सुग्रीव) का शोक दूर किया।"),
 (S,"अंगद के संग लेन गये सिय, खोज कपीस यह बैन उचारो।\nजीवत ना बचिहौ हम सों जु, बिना सुधि लाय इहाँ पगु धारो।\nहेरि थके तट सिंधु सबै तब, लाय सिया सुधि प्राण उबारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","सीता की खोज में अंगद के साथ गए वानरों से सुग्रीव ने कहा था कि बिना खबर लाए लौटे तो जीवित नहीं बचोगे। सब समुद्र-तट पर ढूँढकर थक गए, तब आपने सीता की खबर लाकर सबके प्राण बचाए।"),
 (S,"रावन त्रास दई सिय को सब, राक्षसि सों कहि सोक निवारो।\nताहि समय हनुमान महाप्रभु, जाय महा रजनीचर मारो।\nचाहत सीय असोक सों आगि सु, दै प्रभु मुद्रिका सोक निवारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","रावण ने सीता को बहुत डराया और राक्षसियों से कहा कि उनका शोक (मन) बदलें। उसी समय आपने जाकर बड़े-बड़े राक्षस मारे; जब सीता अशोक वृक्ष से आग माँग रही थीं, आपने प्रभु की अँगूठी देकर उनका शोक दूर किया।"),
 (S,"बान लग्यो उर लछिमन के तब, प्रान तजे सुत रावन मारो।\nलै गृह बैद्य सुषेन समेत, तबै गिरि द्रोन सु बीर उपारो।\nआनि सजीवन हाथ दई तब, लछिमन के तुम प्रान उबारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","मेघनाद का बाण लक्ष्मण की छाती में लगा और उनके प्राण संकट में थे; आप वैद्य सुषेण को घर सहित ले आए, द्रोणगिरि पर्वत उखाड़ लाए और संजीवनी देकर लक्ष्मण के प्राण बचाए।"),
 (S,"रावन जुद्ध अजान कियो तब, नाग कि फाँस सबै सिर डारो।\nश्रीरघुनाथ समेत सबै दल, मोह भयो यह संकट भारो।\nआनि खगेस तबै हनुमान जु, बंधन काटि सुत्रास निवारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","युद्ध में (मेघनाद ने) नागपाश से श्रीराम सहित पूरी सेना को बाँध दिया — यह भारी संकट था; तब आप गरुड़ को ले आए, जिन्होंने बंधन काटकर डर दूर किया।"),
 (S,"बंधु समेत जबै अहिरावन, लै रघुनाथ पताल सिधारो।\nदेबिहिं पूजि भली बिधि सों बलि, देउ सबै मिलि मंत्र बिचारो।\nजाय सहाय भयो तब ही, अहिरावन सैन्य समेत सँहारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","जब अहिरावण राम-लक्ष्मण को पाताल ले गया और देवी को उनकी बलि देने की योजना बनाई, तब आपने जाकर सहायता की और अहिरावण को सेना सहित मार डाला।"),
 (S,"काज किये बड़ देवन के तुम, बीर महाप्रभु देखि बिचारो।\nकौन सो संकट मोर गरीब को, जो तुमसों नहिं जात है टारो।\nबेगि हरो हनुमान महाप्रभु, जो कछु संकट होय हमारो।\nको नहिं जानत है जग में कपि, संकटमोचन नाम तिहारो॥","हे वीर महाप्रभु, आपने देवताओं के बड़े-बड़े काम किए हैं — ज़रा सोचिए, मुझ गरीब का ऐसा कौन-सा संकट है जो आपसे टल न सके? हे हनुमान, हमारा जो भी संकट हो, उसे जल्दी हर लीजिए।"),
 (D,"लाल देह लाली लसे, अरु धरि लाल लंगूर।\nवज्र देह दानव दलन, जय जय जय कपि सूर॥","लाल शरीर पर लाल सिंदूर शोभा देता है और पूँछ भी लाल है; वज्र जैसे शरीर वाले, दानवों का नाश करने वाले वीर कपि की जय हो।"),
]

SANKATNASHAN_GANESH = [
 (S,"प्रणम्य शिरसा देवं गौरीपुत्रं विनायकम्।\nभक्तावासं स्मरेन्नित्यमायुःकामार्थसिद्धये॥","(नारद जी कहते हैं) गौरी-पुत्र विनायक देव को सिर झुकाकर प्रणाम करें; भक्तों के हृदय में बसने वाले गणेश का रोज़ स्मरण करें, जिससे आयु, कामना और धन की सिद्धि हो।"),
 (S,"प्रथमं वक्रतुण्डं च एकदन्तं द्वितीयकम्।\nतृतीयं कृष्णपिङ्गाक्षं गजवक्त्रं चतुर्थकम्॥","पहला नाम वक्रतुंड, दूसरा एकदंत, तीसरा कृष्णपिंगाक्ष (काली-पीली आँखों वाले), चौथा गजवक्त्र (हाथी के मुख वाले)।"),
 (S,"लम्बोदरं पञ्चमं च षष्ठं विकटमेव च।\nसप्तमं विघ्नराजेन्द्रं धूम्रवर्णं तथाष्टमम्॥","पाँचवाँ लंबोदर, छठा विकट, सातवाँ विघ्नराजेंद्र और आठवाँ धूम्रवर्ण।"),
 (S,"नवमं भालचन्द्रं च दशमं तु विनायकम्।\nएकादशं गणपतिं द्वादशं तु गजाननम्॥","नौवाँ भालचंद्र, दसवाँ विनायक, ग्यारहवाँ गणपति और बारहवाँ गजानन।"),
 (S,"द्वादशैतानि नामानि त्रिसन्ध्यं यः पठेन्नरः।\nन च विघ्नभयं तस्य सर्वसिद्धिकरं प्रभो॥","जो मनुष्य सुबह, दोपहर और शाम इन बारह नामों का पाठ करता है, उसे विघ्नों का डर नहीं रहता; यह सब सिद्धियाँ देने वाला है।"),
 (S,"विद्यार्थी लभते विद्यां धनार्थी लभते धनम्।\nपुत्रार्थी लभते पुत्रान्मोक्षार्थी लभते गतिम्॥","विद्या चाहने वाले को विद्या, धन चाहने वाले को धन, संतान चाहने वाले को संतान और मोक्ष चाहने वाले को मुक्ति मिलती है।"),
 (S,"जपेद्गणपतिस्तोत्रं षड्भिर्मासैः फलं लभेत्।\nसंवत्सरेण सिद्धिं च लभते नात्र संशयः॥","इस गणपति स्तोत्र का जाप करने से छह महीने में फल मिलता है और एक वर्ष में सिद्धि मिलती है — इसमें संदेह नहीं।"),
 (S,"अष्टभ्यो ब्राह्मणेभ्यश्च लिखित्वा यः समर्पयेत्।\nतस्य विद्या भवेत्सर्वा गणेशस्य प्रसादतः॥","जो इसे लिखकर आठ ब्राह्मणों को भेंट करता है, उसे गणेश की कृपा से सारी विद्याएँ प्राप्त होती हैं।"),
]

SHRI_HARI_STOTRAM = [
 (S,"जगज्जालपालं चलत्कण्ठमालं\nशरच्चन्द्रभालं महादैत्यकालम्।\nनभोनीलकायं दुरावारमायं\nसुपद्मासहायं भजेऽहं भजेऽहम्॥","जो संसार के जाल के पालनहार हैं, जिनके गले में माला झूलती है, माथा शरद के चंद्रमा जैसा है, जो बड़े दैत्यों के काल हैं, आकाश जैसे नीले शरीर वाले, अपार माया वाले, लक्ष्मी के साथी — उन हरि का मैं भजन करता हूँ।"),
 (S,"सदाम्भोधिवासं गलत्पुष्पहासं\nजगत्सन्निवासं शतादित्यभासम्।\nगदाचक्रशस्त्रं लसत्पीतवस्त्रं\nहसच्चारुवक्त्रं भजेऽहं भजेऽहम्॥","जो सदा क्षीरसागर में रहते हैं, जिनकी हँसी फूलों जैसी झरती है, जो पूरे जगत में बसते हैं, सौ सूर्यों जैसे तेजस्वी हैं, गदा-चक्र धारण करते हैं, पीले वस्त्र पहनते हैं और जिनका मुख मुस्कुराता है — उन हरि का मैं भजन करता हूँ।"),
 (S,"रमाकण्ठहारं श्रुतिव्रातसारं\nजलान्तर्विहारं धराभारहारम्।\nचिदानन्दरूपं मनोज्ञस्वरूपं\nधृतानेकरूपं भजेऽहं भजेऽहम्॥","जो लक्ष्मी के गले का हार हैं, सब वेदों का सार हैं, जल में विहार करते हैं, धरती का भार हरते हैं, चेतना और आनंद रूप हैं, सुंदर स्वरूप वाले और अनेक रूप धारण करने वाले हैं — उन हरि का भजन करता हूँ।"),
 (S,"जराजन्महीनं परानन्दपीनं\nसमाधानलीनं सदैवानवीनम्।\nजगज्जन्महेतुं सुरानीककेतुं\nत्रिलोकैकसेतुं भजेऽहं भजेऽहम्॥","जो बुढ़ापे और जन्म से रहित हैं, परम आनंद से भरे हैं, समाधि में लीन हैं, सदा नए हैं, जगत की उत्पत्ति का कारण हैं, देव-सेना के ध्वज हैं और तीनों लोकों के एकमात्र सेतु हैं — उन हरि का भजन करता हूँ।"),
 (S,"कृताम्नायगानं खगाधीशयानं\nविमुक्तेर्निदानं हरारातिमानम्।\nस्वभक्तानुकूलं जगद्वृक्षमूलं\nनिरस्तार्तशूलं भजेऽहं भजेऽहम्॥","जिनका वेद गान करते हैं, गरुड़ जिनका वाहन है, जो मुक्ति के मूल हैं, शत्रुओं का घमंड हरते हैं, अपने भक्तों के अनुकूल हैं, जगत रूपी वृक्ष की जड़ हैं और दुखियों का कष्ट मिटाते हैं — उन हरि का भजन करता हूँ।"),
 (S,"समस्तामरेशं द्विरेफाभकेशं\nजगद्बिम्बलेशं हृदाकाशदेशम्।\nसदा दिव्यदेहं विमुक्ताखिलेहं\nसुवैकुण्ठगेहं भजेऽहं भजेऽहम्॥","जो सब देवताओं के स्वामी हैं, जिनके बाल भौंरों जैसे काले हैं, यह जगत जिनकी छाया का अंश है, जो हृदय-आकाश में बसते हैं, दिव्य शरीर वाले, सब इच्छाओं से मुक्त और वैकुंठ में रहने वाले हैं — उन हरि का भजन करता हूँ।"),
 (S,"सुरालीबलिष्ठं त्रिलोकीवरिष्ठं\nगुरूणां गरिष्ठं स्वरूपैकनिष्ठम्।\nसदा युद्धधीरं महावीरवीरं\nमहाम्भोधितीरं भजेऽहं भजेऽहम्॥","जो देवताओं में सबसे बलवान, तीनों लोकों में श्रेष्ठ, गुरुओं के भी गुरु, अपने स्वरूप में स्थित, युद्ध में सदा धीर, महावीरों के वीर और संसार-सागर का किनारा हैं — उन हरि का भजन करता हूँ।"),
 (S,"रमावामभागं तलानग्ननागं\nकृताधीनयागं गतारागरागम्।\nमुनीन्द्रैः सुगीतं सुरैः संपरीतं\nगुणौघैरतीतं भजेऽहं भजेऽहम्॥","जिनके बाएँ भाग में लक्ष्मी हैं, जो शेषनाग पर विराजते हैं, यज्ञ जिनके अधीन हैं, जो राग-द्वेष से परे हैं, मुनि जिनका गान करते हैं, देवता जिन्हें घेरे रहते हैं और जो सब गुणों से परे हैं — उन हरि का भजन करता हूँ।"),
 (D,"इदं यस्तु नित्यं समाधाय चित्तं\nपठेदष्टकं कण्ठहारं मुरारेः।\nस विष्णोर्विशोकं ध्रुवं याति लोकं\nजराजन्मशोकं पुनर्विन्दते नो॥","जो मन लगाकर रोज़ मुरारी के गले के हार जैसे इस अष्टक का पाठ करता है, वह निश्चय ही शोक-रहित विष्णुलोक को जाता है और फिर बुढ़ापे, जन्म और शोक को नहीं पाता।"),
]

DASHRATH_SHANI_STOTRA = [
 (S,"नमः कृष्णाय नीलाय शितिकण्ठनिभाय च।\nनमः कालाग्निरूपाय कृतान्ताय च वै नमः॥","काले, नीले, नीलकंठ जैसे वर्ण वाले, प्रलय की अग्नि जैसे और यम रूप शनिदेव को नमस्कार।"),
 (S,"नमो निर्मांसदेहाय दीर्घश्मश्रुजटाय च।\nनमो विशालनेत्राय शुष्कोदर भयाकृते॥","दुबले शरीर वाले, लंबी दाढ़ी-जटाओं वाले, बड़ी आँखों वाले, सूखे पेट वाले और भयानक आकृति वाले शनिदेव को नमस्कार।"),
 (S,"नमः पुष्कलगात्राय स्थूलरोम्णेऽथ वै नमः।\nनमो दीर्घाय शुष्काय कालदंष्ट्र नमोऽस्तु ते॥","विशाल शरीर वाले, मोटे रोम वाले, लंबे, सूखे और काल जैसी दाढ़ों वाले शनिदेव, आपको नमस्कार।"),
 (S,"नमस्ते कोटराक्षाय दुर्निरीक्ष्याय वै नमः।\nनमो घोराय रौद्राय भीषणाय कपालिने॥","गहरी आँखों वाले, जिन्हें देख पाना कठिन है, घोर, रौद्र, भीषण और कपाल धारण करने वाले शनिदेव को नमस्कार।"),
 (S,"नमस्ते सर्वभक्षाय बलीमुख नमोऽस्तु ते।\nसूर्यपुत्र नमस्तेऽस्तु भास्करेऽभयदाय च॥","सबको खा जाने वाले, बलवान मुख वाले, सूर्यपुत्र और अभय देने वाले शनिदेव, आपको नमस्कार।"),
 (S,"अधोदृष्टे नमस्तेऽस्तु संवर्तक नमोऽस्तु ते।\nनमो मन्दगते तुभ्यं निस्त्रिंशाय नमोऽस्तुते॥","नीचे देखने वाले, प्रलय करने वाले, धीमी चाल वाले और तलवार जैसे तीखे शनिदेव, आपको नमस्कार।"),
 (S,"तपसा दग्धदेहाय नित्यं योगरताय च।\nनमो नित्यं क्षुधार्ताय अतृप्ताय च वै नमः॥","तप से तपे शरीर वाले, सदा योग में लगे रहने वाले, सदा भूखे और कभी तृप्त न होने वाले शनिदेव को नमस्कार।"),
 (S,"ज्ञानचक्षुर्नमस्तेऽस्तु कश्यपात्मजसूनवे।\nतुष्टो ददासि वै राज्यं रुष्टो हरसि तत्क्षणात्॥","ज्ञान रूपी आँख वाले, कश्यप के पौत्र (सूर्य के पुत्र), आपको नमस्कार; आप प्रसन्न होकर राज्य दे देते हैं और रूठकर उसी क्षण छीन लेते हैं।"),
 (S,"देवासुरमनुष्याश्च सिद्धविद्याधरोरगाः।\nत्वया विलोकिताः सर्वे नाशं यान्ति समूलतः॥","देवता, असुर, मनुष्य, सिद्ध, विद्याधर और नाग — आपकी (क्रूर) दृष्टि पड़ते ही सब जड़ से नष्ट हो जाते हैं।"),
 (S,"प्रसादं कुरु मे सौरे वरदो भव भास्करे।\nएवं स्तुतस्तदा सौरिर्ग्रहराजो महाबलः॥","हे सूर्यपुत्र, मुझ पर कृपा कीजिए और वर दीजिए — (राजा दशरथ के) इस प्रकार स्तुति करने पर महाबली ग्रहराज शनि प्रसन्न हुए।"),
]

MAHALAKSHMI_ASHTAKAM = [
 (S,"नमस्तेऽस्तु महामाये श्रीपीठे सुरपूजिते।\nशङ्खचक्रगदाहस्ते महालक्ष्मि नमोऽस्तु ते॥","हे महामाया, श्रीपीठ पर विराजने वाली, देवताओं से पूजित, हाथों में शंख, चक्र और गदा धारण करने वाली महालक्ष्मी, आपको नमस्कार।"),
 (S,"नमस्ते गरुडारूढे कोलासुरभयङ्करि।\nसर्वपापहरे देवि महालक्ष्मि नमोऽस्तु ते॥","गरुड़ पर सवार, कोलासुर को भयभीत करने वाली, सब पाप हरने वाली देवी महालक्ष्मी, आपको नमस्कार।"),
 (S,"सर्वज्ञे सर्ववरदे सर्वदुष्टभयङ्करि।\nसर्वदुःखहरे देवि महालक्ष्मि नमोऽस्तु ते॥","सब कुछ जानने वाली, सबको वर देने वाली, सब दुष्टों को डराने वाली, सब दुख हरने वाली देवी महालक्ष्मी, आपको नमस्कार।"),
 (S,"सिद्धिबुद्धिप्रदे देवि भुक्तिमुक्तिप्रदायिनि।\nमन्त्रमूर्ते सदा देवि महालक्ष्मि नमोऽस्तु ते॥","सिद्धि और बुद्धि देने वाली, भोग और मोक्ष देने वाली, मंत्र-स्वरूपा देवी महालक्ष्मी, आपको नमस्कार।"),
 (S,"आद्यन्तरहिते देवि आद्यशक्ति महेश्वरि।\nयोगजे योगसम्भूते महालक्ष्मि नमोऽस्तु ते॥","आदि और अंत से रहित, आदिशक्ति, महेश्वरी, योग से उत्पन्न होने वाली देवी महालक्ष्मी, आपको नमस्कार।"),
 (S,"स्थूलसूक्ष्ममहारौद्रे महाशक्ति महोदरे।\nमहापापहरे देवि महालक्ष्मि नमोऽस्तु ते॥","स्थूल और सूक्ष्म दोनों रूपों वाली, अत्यंत रौद्र, महाशक्ति, विशाल उदर वाली, बड़े पाप हरने वाली देवी महालक्ष्मी, आपको नमस्कार।"),
 (S,"पद्मासनस्थिते देवि परब्रह्मस्वरूपिणि।\nपरमेशि जगन्मातर्महालक्ष्मि नमोऽस्तु ते॥","कमल पर बैठी, परब्रह्म-स्वरूपा, परमेश्वरी, जगत की माता महालक्ष्मी, आपको नमस्कार।"),
 (S,"श्वेताम्बरधरे देवि नानालङ्कारभूषिते।\nजगत्स्थिते जगन्मातर्महालक्ष्मि नमोऽस्तु ते॥","सफ़ेद वस्त्र धारण करने वाली, अनेक आभूषणों से सजी, पूरे जगत में व्याप्त जगन्माता महालक्ष्मी, आपको नमस्कार।"),
 (D,"महालक्ष्म्यष्टकं स्तोत्रं यः पठेद्भक्तिमान्नरः।\nसर्वसिद्धिमवाप्नोति राज्यं प्राप्नोति सर्वदा॥","जो भक्तिमान मनुष्य यह महालक्ष्मी अष्टक पढ़ता है, वह सब सिद्धियाँ और सदा राज्य (वैभव) पाता है।"),
 (D,"एककाले पठेन्नित्यं महापापविनाशनम्।\nद्विकालं यः पठेन्नित्यं धनधान्यसमन्वितः॥","रोज़ एक बार पढ़ने से बड़े पाप नष्ट होते हैं; रोज़ दो बार पढ़ने वाला धन-धान्य से भरा रहता है।"),
 (D,"त्रिकालं यः पठेन्नित्यं महाशत्रुविनाशनम्।\nमहालक्ष्मीर्भवेन्नित्यं प्रसन्ना वरदा शुभा॥","रोज़ तीन बार पढ़ने से बड़े शत्रुओं का नाश होता है और शुभ, वर देने वाली महालक्ष्मी सदा प्रसन्न रहती हैं।"),
]

SAPTASHLOKI_DURGA = [
 (S,"ज्ञानिनामपि चेतांसि देवी भगवती हि सा।\nबलादाकृष्य मोहाय महामाया प्रयच्छति॥","वे भगवती महामाया ज्ञानियों के मन को भी बलपूर्वक खींचकर मोह में डाल देती हैं।"),
 (S,"दुर्गे स्मृता हरसि भीतिमशेषजन्तोः\nस्वस्थैः स्मृता मतिमतीव शुभां ददासि।\nदारिद्र्यदुःखभयहारिणि का त्वदन्या\nसर्वोपकारकरणाय सदार्द्रचित्ता॥","हे दुर्गे, याद करने पर आप सब प्राणियों का डर हर लेती हैं और स्वस्थ मन से याद करने वालों को बहुत शुभ बुद्धि देती हैं। हे दरिद्रता, दुख और भय हरने वाली, आपके सिवा कौन है जिसका मन सबका भला करने के लिए सदा दया से भरा रहता हो?"),
 (S,"सर्वमङ्गलमाङ्गल्ये शिवे सर्वार्थसाधिके।\nशरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते॥","हे सब मंगलों का मंगल करने वाली, कल्याणी, सब काम सिद्ध करने वाली, शरण देने वाली, तीन नेत्रों वाली गौरी नारायणी, आपको नमस्कार।"),
 (S,"शरणागतदीनार्तपरित्राणपरायणे।\nसर्वस्यार्तिहरे देवि नारायणि नमोऽस्तु ते॥","शरण में आए दीनों और दुखियों की रक्षा में लगी रहने वाली, सबकी पीड़ा हरने वाली देवी नारायणी, आपको नमस्कार।"),
 (S,"सर्वस्वरूपे सर्वेशे सर्वशक्तिसमन्विते।\nभयेभ्यस्त्राहि नो देवि दुर्गे देवि नमोऽस्तु ते॥","हे सर्व-स्वरूपा, सबकी स्वामिनी, सब शक्तियों से युक्त देवी, हमें भय से बचाइए; हे दुर्गा देवी, आपको नमस्कार।"),
 (S,"रोगानशेषानपहंसि तुष्टा\nरुष्टा तु कामान् सकलानभीष्टान्।\nत्वामाश्रितानां न विपन्नराणां\nत्वामाश्रिता ह्याश्रयतां प्रयान्ति॥","प्रसन्न होकर आप सारे रोग नष्ट कर देती हैं और रूठकर सारी इच्छित वस्तुएँ छीन लेती हैं। जो आपकी शरण में हैं, उन पर विपत्ति नहीं आती; वे तो दूसरों को शरण देने वाले बन जाते हैं।"),
 (S,"सर्वाबाधाप्रशमनं त्रैलोक्यस्याखिलेश्वरि।\nएवमेव त्वया कार्यमस्मद्वैरिविनाशनम्॥","हे तीनों लोकों की स्वामिनी, इसी तरह आप सारी बाधाएँ शांत कीजिए और हमारे शत्रुओं का नाश कीजिए।"),
]

JYOTIRLINGA_STOTRA = [
 (S,"सौराष्ट्रे सोमनाथं च श्रीशैले मल्लिकार्जुनम्।\nउज्जयिन्यां महाकालमोङ्कारममलेश्वरम्॥","सौराष्ट्र (गुजरात) में सोमनाथ, श्रीशैल (आंध्र प्रदेश) में मल्लिकार्जुन, उज्जैन (मध्य प्रदेश) में महाकाल, और ओंकारेश्वर में ममलेश्वर।"),
 (S,"परल्यां वैद्यनाथं च डाकिन्यां भीमशङ्करम्।\nसेतुबन्धे तु रामेशं नागेशं दारुकावने॥","परली (महाराष्ट्र/देवघर) में वैद्यनाथ, डाकिनी (महाराष्ट्र) में भीमाशंकर, सेतुबंध में रामेश्वरम्, और दारुका वन में नागेश्वर।"),
 (S,"वाराणस्यां तु विश्वेशं त्र्यम्बकं गौतमीतटे।\nहिमालये तु केदारं घुश्मेशं च शिवालये॥","वाराणसी में काशी विश्वनाथ, गोदावरी (गौतमी) तट पर त्र्यंबकेश्वर, हिमालय में केदारनाथ, और शिवालय (वेरुल) में घृष्णेश्वर।"),
 (D,"एतानि ज्योतिर्लिङ्गानि सायं प्रातः पठेन्नरः।\nसप्तजन्मकृतं पापं स्मरणेन विनश्यति॥","जो मनुष्य सुबह-शाम इन बारह ज्योतिर्लिंगों का पाठ करता है, उसके सात जन्मों के पाप स्मरण मात्र से नष्ट हो जाते हैं।"),
]

KRISHNASHTAKAM = [
 (S,"भजे व्रजैकमण्डनं समस्तपापखण्डनं\nस्वभक्तचित्तरञ्जनं सदैव नन्दनन्दनम्।\nसुपिच्छगुच्छमस्तकं सुनादवेणुहस्तकं\nअनङ्गरङ्गसागरं नमामि कृष्णनागरम्॥","मैं ब्रज के एकमात्र आभूषण, सब पापों का नाश करने वाले, भक्तों के मन को प्रसन्न करने वाले नंदनंदन का भजन करता हूँ; सिर पर मोरपंख, हाथ में मधुर बाँसुरी वाले, प्रेम के सागर कृष्ण-नागर को नमन।"),
 (S,"मनोजगर्वमोचनं विशाललोललोचनं\nविधूतगोपशोचनं नमामि पद्मलोचनम्।\nकरारविन्दभूधरं स्मितावलोकसुन्दरं\nमहेन्द्रमानदारणं नमामि कृष्णवारणम्॥","कामदेव का घमंड तोड़ने वाले, बड़ी चंचल आँखों वाले, ग्वालों का शोक मिटाने वाले कमल-नयन को नमन; कमल जैसे हाथ पर पर्वत उठाने वाले, मुस्कान से सुंदर, इंद्र का अभिमान तोड़ने वाले कृष्ण को नमन।"),
 (S,"कदम्बसूनकुण्डलं सुचारुगण्डमण्डलं\nव्रजाङ्गनैकवल्लभं नमामि कृष्णदुर्लभम्।\nयशोदया समोदया सगोपया सनन्दया\nयुतं सुखैकदायकं नमामि गोपनायकम्॥","कदंब के फूलों के कुंडल वाले, सुंदर गालों वाले, ब्रज की गोपियों के एकमात्र प्रिय, दुर्लभ कृष्ण को नमन; प्रसन्न यशोदा, गोपों और नंद के साथ रहने वाले, सुख देने वाले गोपनायक को नमन।"),
 (S,"सदैव पादपङ्कजं मदीयमानसे निजं\nदधानमुत्तमालकं नमामि नन्दबालकम्।\nसमस्तदोषशोषणं समस्तलोकपोषणं\nसमस्तगोपमानसं नमामि नन्दलालसम्॥","जो अपने चरण-कमल सदा मेरे मन में रखते हैं, सुंदर घुँघराले बालों वाले नंद के बालक को नमन; सब दोष सुखाने वाले, सब लोकों का पोषण करने वाले, सब ग्वालों के मन में बसने वाले नंदलाल को नमन।"),
 (S,"भुवो भरावतारकं भवाब्धिकर्णधारकं\nयशोमतीकिशोरकं नमामि चित्तचोरकम्।\nदृगन्तकान्तभङ्गिनं सदा सदालसङ्गिनं\nदिने दिने नवं नवं नमामि नन्दसम्भवम्॥","धरती का भार उतारने वाले, संसार-सागर के नाविक, यशोदा के किशोर, चित्त चुराने वाले को नमन; तिरछी सुंदर चितवन वाले, सदा साथ रहने वाले, रोज़ नए-नए लगने वाले नंदनंदन को नमन।"),
 (S,"गुणाकरं सुखाकरं कृपाकरं कृपापरं\nसुरद्विषन्निकन्दनं नमामि गोपनन्दनम्।\nनवीनगोपनागरं नवीनकेलिलम्पटं\nनमामि मेघसुन्दरं तडित्प्रभालसत्पटम्॥","गुणों की खान, सुख की खान, कृपा के भंडार, देवताओं के शत्रुओं का नाश करने वाले गोपनंदन को नमन; नए-नवेले ग्वाले, नई लीलाओं के रसिया, बादल जैसे सुंदर और बिजली जैसे चमकते पीतांबर वाले को नमन।"),
 (S,"समस्तगोपनन्दनं हृदम्बुजैकमोदनं\nनमामि कुञ्जमध्यगं प्रसन्नभानुशोभनम्।\nनिकामकामदायकं दृगन्तचारुसायकं\nरसालवेणुगायकं नमामि कुञ्जनायकम्॥","सब ग्वालों को आनंद देने वाले, हृदय-कमल को खिलाने वाले, कुंजों में विचरने वाले, प्रसन्न सूर्य जैसे शोभायमान को नमन; हर कामना पूरी करने वाले, सुंदर चितवन के बाण वाले, रसीली बाँसुरी बजाने वाले कुंजनायक को नमन।"),
 (S,"विदग्धगोपिकामनोमनोज्ञतल्पशायिनं\nनमामि कुञ्जकानने प्रवृद्धवह्निपायिनम्।\nकिशोरकान्तिरञ्जितं दृगञ्जनं सुशोभितं\nगजेन्द्रमोक्षकारिणं नमामि श्रीविहारिणम्॥","चतुर गोपियों के मन रूपी सुंदर शय्या पर विश्राम करने वाले, कुंज-वन में फैली दावाग्नि को पी जाने वाले को नमन; किशोर कांति से रंगे, काजल लगी आँखों से सुंदर, गजेंद्र को मोक्ष देने वाले श्री-विहारी को नमन।"),
 (D,"यथा तथा यथा तथा तदैव कृष्णसत्कथा\nमया सदैव गीयतां तथा कृपा विधीयताम्।\nप्रमाणिकाष्टकद्वयं जपत्यधीत्य यः पुमान्\nभवेत्स नन्दनन्दने भवे भवे सुभक्तिमान्॥","जैसे भी हो, मैं सदा कृष्ण की पवित्र कथा गाता रहूँ — ऐसी कृपा कीजिए। जो इस अष्टक का पाठ और जप करता है, वह हर जन्म में नंदनंदन का सच्चा भक्त बनता है।"),
]

HANUMAN_DWADASH_NAAM = [
 (S,"हनुमानञ्जनीसूनुर्वायुपुत्रो महाबलः।\nरामेष्टः फाल्गुनसखः पिङ्गाक्षोऽमितविक्रमः॥","1. हनुमान, 2. अंजनीसूनु (अंजनी के पुत्र), 3. वायुपुत्र, 4. महाबल, 5. रामेष्ट (राम के प्रिय), 6. फाल्गुनसखा (अर्जुन के मित्र), 7. पिंगाक्ष (भूरी आँखों वाले), 8. अमितविक्रम (अपार पराक्रमी)।"),
 (S,"उदधिक्रमणश्चैव सीताशोकविनाशनः।\nलक्ष्मणप्राणदाता च दशग्रीवस्य दर्पहा॥","9. उदधिक्रमण (समुद्र लाँघने वाले), 10. सीताशोकविनाशन (सीता का शोक मिटाने वाले), 11. लक्ष्मणप्राणदाता (लक्ष्मण के प्राण बचाने वाले), 12. दशग्रीवदर्पहा (रावण का घमंड तोड़ने वाले)।"),
 (S,"एवं द्वादश नामानि कपीन्द्रस्य महात्मनः।\nस्वापकाले प्रबोधे च यात्राकाले च यः पठेत्॥","महात्मा कपीश्वर के इन बारह नामों का जो सोते समय, जागते समय और यात्रा पर निकलते समय पाठ करता है,"),
 (S,"तस्य सर्वभयं नास्ति रणे च विजयी भवेत्।\nराजद्वारे गह्वरे च भयं नास्ति कदाचन॥","उसे कोई भय नहीं रहता, वह संघर्ष में विजयी होता है, और राज-दरबार (कचहरी) या संकट की जगह पर भी उसे कभी डर नहीं लगता।"),
]
